            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterE = (aWandererE + RotL64(aScatter, 22U)) + 0x9B68544673017810ULL;
            aOrbiterK = (aWandererA + RotL64(aCross, 5U)) + 0x5D39D0E2BB27F509ULL;
            aOrbiterF = ((aWandererK + RotL64(aPrevious, 35U)) + 0x7294FA8596B7783AULL) + aTwistOrbiterAssignSaltF[(((255U - aIndex) + 197U)) & S_SALT1];
            aOrbiterI = ((aWandererF + RotL64(aIngress, 29U)) + RotL64(aCarry, 57U)) + 0x48D2E1D849B1B932ULL;
            aOrbiterB = ((aWandererJ + RotL64(aPrevious, 18U)) + RotL64(aCarry, 13U)) + 0xD3CA46184E531E46ULL;
            aOrbiterG = (aWandererB + RotL64(aCross, 13U)) + 0x34E9D7E2D48208FEULL;
            aOrbiterJ = (aWandererI + RotL64(aIngress, 51U)) + 0xCC1A314CA6F1ECE4ULL;
            aOrbiterH = ((aWandererD + RotL64(aScatter, 43U)) + RotL64(aCarry, 41U)) + 0x2EE749B87CBC28BAULL;
            aOrbiterC = ((aWandererH + RotL64(aPrevious, 57U)) + 0x01C9F186F20478DDULL) + aTwistOrbiterAssignSaltB[((aIndex + 89U)) & S_SALT1];
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0x2EB6F8CE751A7AA5ULL) + aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 78U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x645CFCCFCE7EC722ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x6F1DEAA4285A8B17ULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x02F23EA2AC0473ADULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0xC98F24E055459A54ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xAAB452CA03AAAA0FULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x0AAEC6D4189C2A58ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0xB5017CFD5875B69EULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x944CD7CE2C9C9893ULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x7E69854D17AC5CE7ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xFA9DA0F7CD0A7916ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x7C96B35593AF2039ULL), 35U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0xC9FC5ABBC534A167ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 38U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xD0B64F63B3E6A14BULL;
            aOrbiterC = RotL64((aOrbiterC * 0x05E05F8CAF448C31ULL), 19U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x07B4F84B90767F56ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x6CC25B61E8225DA8ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 33U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xB58D6C728C3EEAEBULL), 23U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0xD3942A647015BB5CULL) + aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 35U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0xD60989ECF7B7363EULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1C4652B51B9407A5ULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x4EA32020D50FD1FCULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x787E5D958B2FD730ULL;
