            aWandererE = aWandererE ^ ((RotL64(aCross, 11U) + RotL64(aOrbiterJ, 57U)) + aOrbiterE);
            aWandererG = aWandererG + ((((RotL64(aScatter, 29U) + aOrbiterA) + RotL64(aOrbiterD, 36U)) + RotL64(aCarry, 13U)) + aTwistWandererUpdateSaltA[((aIndex + 25U)) & S_SALT1]);
