            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x850F7E0506C28861ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterI) ^ 0x06998B9B02304219ULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((255U - aIndex) + 249U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xDACDD894D227F5CBULL), 27U);
